from scipy.optimize import least_squares
def run(name, model, p0s, trials=6):
    bestr=None
    rng=np.random.default_rng(1)
    for k in range(trials):
        p0=p0s+rng.normal(0,0.05,len(p0s))*(k>0)
        try:
            r=least_squares(lambda p: model(p,eps,T)-sigma, p0, max_nfev=3000)
        except Exception as ex:
            continue
        if not np.all(np.isfinite(r.fun)): continue
        if bestr is None or r.cost<bestr.cost: bestr=r
    if bestr is None: print(name,"failed"); return
    print(name, np.mean(bestr.fun**2)/np.var(sigma), np.round(bestr.x,3))
# cubic in T for each function
def P3(p,e,t):
    a=p[0]+p[1]*t+p[2]*t**2+p[3]*t**3
    b=p[4]+p[5]*t+p[6]*t**2+p[7]*t**3
    c=p[8]+p[9]*t+p[10]*t**2+p[11]*t**3
    return a+b*e*np.exp(-c*e)
