def Pinv(p,e,t):
    a=p[0]+p[1]*t+p[2]*t**2
    b=p[3]+p[4]*t+p[5]*t**2
    c=p[6]+p[7]*t+p[8]/t
    return a+b*e*np.exp(-c*e)+p[9]*np.log(e)
